251	void cfl_variant_destroy(struct cfl_variant *instance)
252	{
253	    if (!instance) {
254	        return;
255	    }
256	
257	    if (instance->type == CFL_VARIANT_STRING ||
258	        instance->type == CFL_VARIANT_BYTES) {
259	        if (instance->data.as_string != NULL) {
260	            cfl_sds_destroy(instance->data.as_string);
261	        }
262	    }
263	    else if (instance->type == CFL_VARIANT_ARRAY) {
264	        cfl_array_destroy(instance->data.as_array);
265	    }
266	    else if (instance->type == CFL_VARIANT_KVLIST) {
267	        cfl_kvlist_destroy(instance->data.as_kvlist);
268	    }
269	
270	    free(instance);
271	}
