40	void cfl_kvlist_destroy(struct cfl_kvlist *list)
41	{
42	    struct cfl_list *tmp;
43	    struct cfl_list *head;
44	    struct cfl_kvpair *pair;
45	
46	    cfl_list_foreach_safe(head, tmp, &list->list) {
47	        pair = cfl_list_entry(head, struct cfl_kvpair, _head);
48	
49	        if (pair->key) {
50	            cfl_sds_destroy(pair->key);
51	        }
52	
53	        if (pair->val) {
54	            cfl_variant_destroy(pair->val);
55	        }
56	        cfl_list_del(&pair->_head);
57	        free(pair);
58	    }
59	
60	    free(list);
61	}
